const isRenderableRemoteMediaUri = (value: any): boolean => {
  const uri = String(value || '').trim();
  if (!uri) return false;
  if (/^https?:\/\//i.test(uri)) return true;
  if (/^gs:\/\//i.test(uri)) return true;
  return false;
};
                    
const isVideoAsset = (asset: Asset | null | undefined): boolean => {
  if (!asset) return false;
  const t = (asset.type || '').toLowerCase();
  if (t.includes('video')) return true;
  const uri = String(asset.uri || '').toLowerCase();
  if (/(\.(mp4|mov|m4v|webm|3gp|3gpp|mkv|avi))($|\?)/i.test(uri)) return true;
  const isLocal = uri.startsWith('file://') || uri.startsWith('content://');
  const isImageExt = /(\.(jpg|jpeg|png|gif|heic|webp))($|\?)/i.test(uri);
  if (isLocal && !isImageExt) return true;
  return false;
};

const isAudioAsset = (asset: Asset | null | undefined): boolean => {
  if (!asset) return false;
  const t = (asset.type || '').toLowerCase();
  if (t.includes('audio')) return true;
  const uri = String(asset.uri || '').toLowerCase();
  return /(\.(mp3|m4a|aac|wav|ogg|flac))($|\?)/i.test(uri);
};

const isImageAsset = (asset: Asset | null | undefined): boolean => {
  if (!asset) return false;
  const t = (asset.type || '').toLowerCase();
  if (t.includes('image')) return true;
  const uri = String(asset.uri || '').toLowerCase();
  return /(\.(jpg|jpeg|png|gif|webp|heic))($|\?)/i.test(uri);
};

