const buildTextOverlay = (
  text: string,
  preset: CaptionStylePreset,
  previous?: TextOverlay | null,
): TextOverlay => {
  const presetStyle = getTextOverlayPresetStyle({ stylePreset: preset } as TextOverlay);
  return {
    text,
    x: previous?.x ?? 0.5,
    y: previous?.y ?? 0.72,
    fontSize: previous?.fontSize ?? 28,
    color: presetStyle.textColor,
    fontWeight: preset === 'plain' ? '700' : '800',
    rotation: previous?.rotation ?? 0,
    textAlign: 'center',
    stylePreset: preset,
    backgroundColor:
      presetStyle.backgroundColor === 'transparent'
        ? null
        : presetStyle.backgroundColor,
    paddingHorizontal: presetStyle.paddingHorizontal,
    paddingVertical: presetStyle.paddingVertical,
    borderRadius: presetStyle.borderRadius,
    shadow: presetStyle.shadow,
    animationPreset: presetStyle.animationPreset,
  };
};

const buildPointerOverlay = (
  option: (typeof POINTER_OPTIONS)[number],
  previous?: TextOverlay | null,
): TextOverlay => {
  const next = buildTextOverlay(
    option.symbol,
    previous?.stylePreset || option.preset,
    previous || undefined,
  );
  return {
    ...next,
    text: option.symbol,
    fontSize: previous?.fontSize ?? 42,
    color: previous?.color || '#FF4D4F',
    rotation: previous?.rotation ?? option.defaultRotation ?? 0,
    animationPreset: previous?.animationPreset || next.animationPreset || 'pulse',
  };
};

const sanitizeFirestoreValue = (value: any): any => {
  if (value === undefined) return null;
  if (Array.isArray(value)) {
    return value.map(item => sanitizeFirestoreValue(item));
  }
  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value)
        .filter(([, entry]) => entry !== undefined)
        .map(([key, entry]) => [key, sanitizeFirestoreValue(entry)]),
    );
  }
  return value;
};

const inferMediaSceneHints = (
  rawInputs: Array<string | null | undefined>,
): string[] => {
  const blob = rawInputs
    .filter(Boolean)
    .map(v => String(v).toLowerCase())
    .join(' ');
  if (!blob) return [];

  const rules: Array<{ hint: string; rx: RegExp }> = [
    { hint: 'dancing/performance', rx: /\b(dance|dancing|choreo|choreography|freestyle|performance)\b/i },
    { hint: 'flooded river / fast water flow', rx: /\b(flood|flooded|river|waterfall|rapid|overflow|torrent)\b/i },
    { hint: 'gym/workout/fitness', rx: /\b(gym|workout|fitness|exercise|training|lift)\b/i },
    { hint: 'football/soccer', rx: /\b(football|soccer|goal|pitch|match)\b/i },
    { hint: 'basketball', rx: /\b(basketball|hoop|nba|dunk)\b/i },
    { hint: 'beach/ocean/waves', rx: /\b(beach|ocean|sea|waves|shore|coast)\b/i },
    { hint: 'city/urban street scene', rx: /\b(city|urban|street|traffic|downtown)\b/i },
    { hint: 'nature/outdoors', rx: /\b(nature|forest|mountain|outdoor|sunset|sunrise)\b/i },
    { hint: 'pets/animals', rx: /\b(dog|cat|puppy|kitten|pet|animal)\b/i },
    { hint: 'party/celebration', rx: /\b(party|celebration|birthday|wedding|event)\b/i },
  ];

  return rules.filter(r => r.rx.test(blob)).map(r => r.hint);
};

