const buildLiveInviteNotice = (
  docId: string,
  data: Record<string, any>,
  source: 'inbox' | 'mention' | 'ping',
): LiveInviteNotice | null => {
  if (!data?.fromUid) return null;
  return {
    id: docId,
    source,
    liveId: String(data.liveId || ''),
    fromUid: String(data.fromUid || ''),
    fromName: String(data.fromName || 'Skipper'),
    fromPhoto: data.fromPhoto || null,
    liveTitle: data.liveTitle || null,
    liveChannel: data.liveChannel ? String(data.liveChannel) : null,
    liveToken: data.liveToken ? String(data.liveToken) : null,
    directCallId: data.directCallId ? String(data.directCallId) : null,
    directCallChannel: data.directCallChannel
      ? String(data.directCallChannel)
      : null,
    callType: data.callType === 'audio' ? 'audio' : 'video',
    createdAtMs: toJSDate(data.createdAt).getTime() || 0,
    expiresAtMs: Number(data.expiresAtMs || 0) || 0,
  };
};

const buildWaveMediaItems = (data: any): Asset[] => {
  const out: Asset[] = [];
  const rawItems = Array.isArray(data?.galleryItems)
    ? data.galleryItems
    : Array.isArray(data?.mediaItems)
    ? data.mediaItems
    : Array.isArray(data?.media)
    ? data.media
    : [];
  rawItems.forEach((entry: any) => {
    const uri = String(
      entry?.uri ||
        entry?.mediaUrl ||
        entry?.url ||
        entry?.downloadURL ||
        entry?.downloadUrl ||
        entry?.playbackUrl ||
        '',
    ).trim();
    if (!isRenderableRemoteMediaUri(uri)) return;
    out.push({
      uri,
      type: entry?.type || entry?.mediaType || entry?.mimeType || undefined,
      fileName: entry?.fileName || entry?.name || undefined,
    } as Asset);
  });
  if (out.length > 0) return out;
  const legacyMedia = data?.media && !Array.isArray(data.media) ? data.media : null;
  if (legacyMedia) {
    const legacyUri = String(
      legacyMedia?.uri ||
        legacyMedia?.mediaUrl ||
        legacyMedia?.url ||
        legacyMedia?.downloadURL ||
        legacyMedia?.downloadUrl ||
        legacyMedia?.playbackUrl ||
        '',
    ).trim();
    if (isRenderableRemoteMediaUri(legacyUri)) {
      return [
        {
          uri: legacyUri,
          type: legacyMedia?.type || legacyMedia?.mediaType || legacyMedia?.mimeType || data?.mediaType || undefined,
          fileName: legacyMedia?.fileName || legacyMedia?.name || undefined,
        } as Asset,
      ];
    }
  }
  const fallbackUri = String(data?.playbackUrl || data?.mediaUrl || '').trim();
  if (!isRenderableRemoteMediaUri(fallbackUri)) return [];
  const mediaType = data?.mediaType || undefined;
  return [{ uri: fallbackUri, type: mediaType }] as Asset[];
};

const buildWavePreviewImage = (data: any, mediaItems?: Asset[] | null): string | null => {
  const directPreview = [
    data?.image,
    data?.thumbnailUrl,
    data?.thumbUrl,
    data?.thumb,
    data?.poster,
    data?.posterUrl,
    data?.previewImageUrl,
    data?.coverImage,
  ]
    .map((value: any) => String(value || '').trim())
    .find(Boolean);

  if (directPreview) {
    return directPreview;
  }

  const firstImage = (Array.isArray(mediaItems) ? mediaItems : [])
    .find(item => {
      const type = String(item?.type || '').toLowerCase();
      const uri = String(item?.uri || '').toLowerCase();
      return type.startsWith('image/') || /(\.jpg|\.jpeg|\.png|\.gif|\.webp|\.heic)(\?|$)/i.test(uri);
    });

  return firstImage?.uri ? String(firstImage.uri) : null;
};

const resolveWaveStoredUrl = (data: any): string | null => {
  const direct = [
    data?.playbackUrl,
    data?.mediaUrl,
    data?.videoUrl,
    data?.imageUrl,
    data?.downloadURL,
    data?.downloadUrl,
    data?.fileUrl,
    data?.fileURL,
    data?.media?.uri,
    data?.media?.url,
    data?.media?.mediaUrl,
    data?.media?.downloadURL,
    data?.media?.downloadUrl,
    data?.media?.playbackUrl,
  ]
    .map((value: any) => String(value || '').trim())
    .find(isRenderableRemoteMediaUri);

  if (direct) {
    return direct;
  }

  const mediaPath = String(data?.mediaPath || '').trim();
  if (isRenderableRemoteMediaUri(mediaPath)) {
    return mediaPath;
  }

  const firstItemUri = buildWaveMediaItems(data).find(item => !!item?.uri)?.uri;
  return firstItemUri ? String(firstItemUri) : null;
};

const preserveExistingGridWave = (existingWave: Vibe | undefined, nextWave: Vibe): Vibe => {
  const existingItems = Array.isArray(existingWave?.mediaItems)
    ? existingWave.mediaItems.filter(item => isRenderableRemoteMediaUri(item?.uri))
    : [];
  const nextItems = Array.isArray(nextWave?.mediaItems)
    ? nextWave.mediaItems.filter(item => isRenderableRemoteMediaUri(item?.uri))
    : [];
  if (existingItems.length > 1 && nextItems.length <= 1) {
    return {
      ...nextWave,
      mediaItems: existingItems,
      media:
        nextWave.media ||
        existingWave?.media ||
        existingItems[0] ||
        null,
      postType: nextWave.postType || existingWave?.postType || 'gallery',
    };
  }
  return nextWave;
};

const preserveExistingGridCollection = (existingWaves: Vibe[], nextWaves: Vibe[]): Vibe[] => {
  const existingById = new Map(existingWaves.map(wave => [wave.id, wave]));
  return nextWaves.map(nextWave =>
    preserveExistingGridWave(existingById.get(nextWave.id), nextWave),
  );
};

const getWaveMediaItemCount = (wave: Vibe | null | undefined): number => {
  if (Array.isArray(wave?.mediaItems)) {
    return wave.mediaItems.filter(item => isRenderableRemoteMediaUri(item?.uri)).length;
  }
  return isRenderableRemoteMediaUri(wave?.media?.uri) ? 1 : 0;
};

const mergeWaveVersions = (existingWave: Vibe | undefined, nextWave: Vibe): Vibe => {
  if (!existingWave) return nextWave;

  const preservedNextWave = preserveExistingGridWave(existingWave, nextWave);
  const existingCount = getWaveMediaItemCount(existingWave);
  const nextCount = getWaveMediaItemCount(preservedNextWave);
  const preferredWave = nextCount >= existingCount ? preservedNextWave : existingWave;
  const fallbackWave = preferredWave === preservedNextWave ? existingWave : preservedNextWave;

  return {
    ...fallbackWave,
    ...preferredWave,
    mediaItems:
      nextCount >= existingCount
        ? preservedNextWave.mediaItems || existingWave.mediaItems || null
        : existingWave.mediaItems || preservedNextWave.mediaItems || null,
    media:
      preferredWave.media ||
      fallbackWave.media ||
      (nextCount > 0
        ? (preservedNextWave.mediaItems?.find(item => !!item?.uri) as any) || null
        : null),
    postType:
      nextCount > 1 || existingCount > 1
        ? 'gallery'
        : preferredWave.postType || fallbackWave.postType || null,
    captionText: preferredWave.captionText || fallbackWave.captionText || '',
    playbackUrl: preferredWave.playbackUrl || fallbackWave.playbackUrl || null,
    authorName: preferredWave.authorName || fallbackWave.authorName || null,
    ownerUid: preferredWave.ownerUid || fallbackWave.ownerUid || null,
    user: preferredWave.user || fallbackWave.user || null,
    image: preferredWave.image || fallbackWave.image || null,
    mediaEdits: preferredWave.mediaEdits || fallbackWave.mediaEdits || null,
    counts: preferredWave.counts || fallbackWave.counts || {},
    createdAt: preferredWave.createdAt || fallbackWave.createdAt || null,
  };
};

const mergeWaveCollectionsById = (...collections: Vibe[][]): Vibe[] => {
  const merged = new Map<string, Vibe>();
  collections.forEach(collection => {
    collection.forEach(wave => {
      if (!wave?.id) return;
      const existingWave = merged.get(wave.id);
      merged.set(wave.id, mergeWaveVersions(existingWave, wave));
    });
  });
  return Array.from(merged.values());
};

const normalizeStoredGridItems = (items: any[] | null | undefined): Array<{ uri: string; type?: string; fileName?: string }> => {
  if (!Array.isArray(items)) return [];
  return items
    .map(item => ({
      uri: String(item?.uri || item?.mediaUrl || '').trim(),
      type: item?.type || item?.mediaType || undefined,
      fileName: item?.fileName || item?.name || undefined,
    }))
    .filter(item => !!item.uri);
};

const pickLatestLiveInvite = (
  invites: Array<LiveInviteNotice | null | undefined>,
): LiveInviteNotice | null => {
  return (
    invites
      .filter(Boolean)
      .sort(
        (a, b) =>
          Number((b as LiveInviteNotice).createdAtMs || 0) -
          Number((a as LiveInviteNotice).createdAtMs || 0),
      )[0] || null
  ) as LiveInviteNotice | null;
};
