const interpolateTranslation = (
  template: string,
  values?: Record<string, string | number>,
) =>
  Object.entries(values || {}).reduce(
    (text, [key, value]) => text.split(`{{${key}}}`).join(String(value)),
    template,
  );

const normalizeAppLanguage = (value?: string | null): SupportedAppLanguage => {
  const normalized = String(value || '')
    .trim()
    .toLowerCase();
  switch (normalized) {
    case 'en':
    case 'english':
      return 'en';
    case 'sn':
    case 'shona':
    case 'chishona':
      return 'sn';
    case 'nd':
    case 'ndebele':
    case 'isindebele':
      return 'nd';
    case 'sw':
    case 'kiswahili':
    case 'swahili':
      return 'sw';
    case 'system':
    case 'system default':
    default:
      return 'system';
  }
};

const getDeviceLanguageCode = (): ResolvedAppLanguage => {
  const localeCandidate =
    String(
      NativeModules?.I18nManager?.localeIdentifier ||
        NativeModules?.SettingsManager?.settings?.AppleLocale ||
        NativeModules?.SettingsManager?.settings?.AppleLanguages?.[0] ||
        '',
    ).toLowerCase();
  if (localeCandidate.startsWith('sw')) return 'sw';
  if (localeCandidate.startsWith('sn')) return 'sn';
  if (localeCandidate.startsWith('nd')) return 'nd';
  return 'en';
};

const resolveAppLanguage = (
  preference: SupportedAppLanguage,
): ResolvedAppLanguage =>
  preference === 'system' ? getDeviceLanguageCode() : preference;

const getTranslationLabel = (
  language: ResolvedAppLanguage,
  code: SupportedAppLanguage,
) => TRANSLATIONS[language][APP_LANGUAGE_OPTIONS.find(option => option.code === code)?.labelKey || 'language.english'];

type AppLanguageContextValue = {
  languagePreference: SupportedAppLanguage;
  resolvedLanguage: ResolvedAppLanguage;
  setLanguagePreference: (language: SupportedAppLanguage) => Promise<void>;
  t: (key: TranslationKey, values?: Record<string, string | number>) => string;
};

const AppLanguageContext = createContext<AppLanguageContextValue | null>(null);

const AppLanguageProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [languagePreference, setLanguagePreferenceState] =
    useState<SupportedAppLanguage>('system');

  useEffect(() => {
    let mounted = true;
    const loadLanguagePreference = async () => {
      try {
        const raw = await AsyncStorage.getItem(HARBOR_SETTINGS_STORAGE_KEY);
        if (!mounted || !raw) return;
        const parsed = JSON.parse(raw || '{}') || {};
        setLanguagePreferenceState(normalizeAppLanguage(parsed?.appLanguage));
      } catch {}
    };
    loadLanguagePreference();
    return () => {
      mounted = false;
    };
  }, []);

  const resolvedLanguage = resolveAppLanguage(languagePreference);

  const setLanguagePreference = useCallback(async (language: SupportedAppLanguage) => {
    const normalized = normalizeAppLanguage(language);
    setLanguagePreferenceState(normalized);
    try {
      const raw = await AsyncStorage.getItem(HARBOR_SETTINGS_STORAGE_KEY);
      const parsed = raw ? JSON.parse(raw || '{}') || {} : {};
      await AsyncStorage.setItem(
        HARBOR_SETTINGS_STORAGE_KEY,
        JSON.stringify({
          ...DEFAULT_HARBOR_SETTINGS,
          ...parsed,
          appLanguage: normalized,
        }),
      );
    } catch {}
  }, []);

  const t = useCallback(
    (key: TranslationKey, values?: Record<string, string | number>) =>
      interpolateTranslation(
        TRANSLATIONS[resolvedLanguage][key] || TRANSLATIONS.en[key] || key,
        values,
      ),
    [resolvedLanguage],
  );

  const contextValue = useMemo(
    () => ({
      languagePreference,
      resolvedLanguage,
      setLanguagePreference,
      t,
    }),
    [languagePreference, resolvedLanguage, setLanguagePreference, t],
  );

  return (
    <AppLanguageContext.Provider value={contextValue}>
      {children}
    </AppLanguageContext.Provider>
  );
};

const useAppLanguage = () => {
  const context = useContext(AppLanguageContext);
  if (!context) {
    throw new Error('useAppLanguage must be used within AppLanguageProvider');
  }
  return context;
};
                    
const toJSDate = (ts: any) => {
  try {
    if (!ts) return new Date(0);
    if (typeof ts?.toDate === 'function') return ts.toDate();
    if (typeof ts?.seconds === 'number') return new Date(ts.seconds * 1000);
    return new Date(ts);
  } catch {
    return new Date(0);
  }
};

const toMillis = (ts: any): number => {
  try {
    if (!ts) return 0;
    if (typeof ts === 'number') return ts;
    if (typeof ts?.toMillis === 'function') return Number(ts.toMillis()) || 0;
    if (typeof ts?.toDate === 'function')
      return Number(ts.toDate().getTime()) || 0;
    if (typeof ts?.seconds === 'number') return ts.seconds * 1000;
    const parsed = new Date(ts).getTime();
    return Number.isFinite(parsed) ? parsed : 0;
  } catch {
    return 0;
  }
};
                    
const getAppVersionInfo = () => {
  const platformConstants: any =
    (NativeModules as any)?.PlatformConstants ||
    (NativeModules as any)?.UIManager?.getConstants?.() ||
    {};
  const pkgVersion = (() => {
    try {
      return require('./package.json')?.version;
    } catch {
      return null;
    }
  })();
  const version =
    platformConstants.appVersion ||
    platformConstants.appVersionName ||
    pkgVersion ||
    '1.0.0';
  const build =
    platformConstants.appBuildNumber ||
    platformConstants.appVersionCode ||
    platformConstants.VersionCode ||
    (platformConstants.Version && platformConstants.Version.build) ||
    '1';
  return { version: String(version), build: String(build) };
};
                    
const fetchBackendVersionInfo = async () => {
  try {
    const cfgModule = require('./liveConfig');
    const cfg =
      cfgModule?.cfg ||
      cfgModule?.default ||
      cfgModule ||
      {};
    const baseUrl =
      cfg.BACKEND_BASE_URL ||
      cfg.USER_MGMT_ENDPOINT_BASE ||
      cfg.USER_MANAGEMENT_BASE_URL ||
      '';
    if (!baseUrl) return null;
    const normalized = baseUrl.endsWith('/')
      ? baseUrl.slice(0, -1)
      : baseUrl;
    const resp = await fetch(`${normalized}/app-version`);
    if (!resp.ok) return null;
    const data = await resp.json();
    if (!data?.version || !data?.build) return null;
    return {
      version: String(data.version),
      build: String(data.build),
      source: data.source || 'backend',
    };
  } catch (err) {
    console.log('Failed to fetch app version from backend:', err);
    return null;
  }
};
                    
function useAppVersionInfo() {
  const [info, setInfo] = useState({
    ...getAppVersionInfo(),
    source: 'native',
  });
                    
  useEffect(() => {
    let cancelled = false;
    (async () => {
      const remote = await fetchBackendVersionInfo();
      if (remote && !cancelled) {
        setInfo(remote);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);
                    
  return info;
}
                    
