// Keep near other top-level helpers, outside components
export const ensureCamMicPermissionsAndroid = async (): Promise<boolean> => {
  if (Platform.OS !== 'android') return true;
  try {
    const results = await PermissionsAndroid.requestMultiple([
      PermissionsAndroid.PERMISSIONS.CAMERA,
      PermissionsAndroid.PERMISSIONS.RECORD_AUDIO,
    ] as any);
    const cam = results[PermissionsAndroid.PERMISSIONS.CAMERA];
    const mic = results[PermissionsAndroid.PERMISSIONS.RECORD_AUDIO];
    const ok =
      cam === PermissionsAndroid.RESULTS.GRANTED &&
      mic === PermissionsAndroid.RESULTS.GRANTED;
    if (!ok) {
      const neverAskAgain =
        cam === PermissionsAndroid.RESULTS.NEVER_ASK_AGAIN ||
        mic === PermissionsAndroid.RESULTS.NEVER_ASK_AGAIN;
      Alert.alert(
        'Permission required',
        neverAskAgain
          ? 'Camera & microphone are permanently denied. Open Settings to enable.'
          : 'Camera & microphone are required to go live.',
        neverAskAgain
          ? [
              { text: 'Cancel', style: 'cancel' },
              { text: 'Open Settings', onPress: () => Linking.openSettings() },
            ]
          : [{ text: 'OK' }],
      );
    }
    return ok;
  } catch (e) {
    console.warn('Permission request failed', e);
    return false;
  }
};

const mapRtcUidFromUserId = (value: string | null | undefined): number => {
  const seed = String(value || '').trim() || '0';
  let hash = 0;
  for (let i = 0; i < seed.length; i += 1) {
    hash = (hash * 31 + seed.charCodeAt(i)) >>> 0;
  }
  return (hash % 2147483646) + 1;
};

const buildBackendUrlCandidates = (rawUrl: string): string[] => {
  const seen = new Set<string>();
  const urls: string[] = [];
  const push = (value: string) => {
    const trimmed = String(value || '').trim();
    if (!trimmed || seen.has(trimmed)) return;
    seen.add(trimmed);
    urls.push(trimmed);
  };

  push(rawUrl);
  try {
    const parsed = new URL(rawUrl);
    const hosts =
      Platform.OS === 'android'
        ? [parsed.hostname, '10.0.2.2', '127.0.0.1', 'localhost']
        : [parsed.hostname, '127.0.0.1', 'localhost'];
    hosts.forEach(host => {
      const next = new URL(parsed.toString());
      next.hostname = host;
      push(next.toString());
    });
  } catch {}

  return urls;
};
                    
