  // Do not render the feed while this screen is not focused (e.g., while Welcome is visible)
  const isFocused = useIsFocused();
                    
  // Back handler logic - TikTok-style: first back toggles feed view, second back exits
  const lastBackPressTime = useRef<number>(0);
  useEffect(() => {
    const onBackPress = () => {
      if (showInbox) {
        if (selectedThread) {
          resetInboxView();
        } else {
          closeInboxModal();
        }
        return true;
      }
      if (showCreatorProfile) {
        setShowCreatorProfile(false);
        return true;
      }
      if (showMyWaves) {
        setShowMyWaves(false);
        return true;
      }
      if (showEchoes) {
        setShowEchoes(false);
        return true;
      }
      if (isFocused) {
        const now = Date.now();
        const timeSinceLastPress = now - lastBackPressTime.current;
                    
        // If less than 2 seconds since last back press, allow app exit
        if (timeSinceLastPress < 2000) {
          return false; // Exit app
        }
                    
        // First back press: go to top of feed
        lastBackPressTime.current = now;
        setCurrentIndex(0);
        try {
          feedRef.current?.scrollToOffset({ offset: 0, animated: false });
        } catch {}
        return true; // We've handled the back press
      }
      // If not focused, let default handler run
      return false;
    };
                    
    const subscription = BackHandler.addEventListener(
      'hardwareBackPress',
      onBackPress,
    );
                    
    return () => subscription.remove();
  }, [
    closeInboxModal,
    isFocused,
    resetInboxView,
    selectedThread,
    showCreatorProfile,
    showEchoes,
    showInbox,
    showMyWaves,
  ]);
                    
  // ----- Profile photo handlers -----
  const uploadAndSave = async (uri: string) => {
    try {
      const uid = auth().currentUser?.uid;
      if (!uid) {
        throw new Error('Please sign in to upload a profile photo.');
      }
      if (
        !(await ensureNetworkActionAllowed('upload', {
          label: 'upload your profile photo',
          kind: 'photos',
          localPath: uri,
        }))
      ) {
        throw new Error('Please use Wi-Fi to upload your profile photo.');
      }

      // Upload to Firebase Storage
      const storageRef = storage().ref(`users/${uid}/profile.jpg`);
      await storageRef.putFile(uri);
      const downloadURL = await storageRef.getDownloadURL();

      // Update Firestore
      await firestore()
        .doc(`users/${uid}`)
        .set({ userPhoto: downloadURL }, { merge: true });

      // Update local state
      setProfilePhoto(downloadURL);
    } catch (error) {
      console.error('Error uploading profile photo:', error);
      throw error;
    }
  };

  const onEditAvatar = async () => {
    try {
      const actions: any[] = [];
      actions.push({
        text: 'Choose Photo',
        onPress: async () => {
          try {
            console.log('Launching image library...');
            const res = await launchImageLibrary({
              mediaType: 'photo',
              selectionLimit: 1,
              includeBase64: false,
              presentationStyle: 'fullScreen',
            });
            console.log('Image library response:', res);
            const a = res?.assets?.[0];
            if (!a?.uri) {
              console.log('No asset selected');
              return;
            }
            console.log('Selected asset:', a);
            await uploadAndSave(String(a.uri));
          } catch (error) {
            console.error('Error in launchImageLibrary:', error);
            showOceanDialog(
              'Photo Selection Error',
              'Failed to select photo. Please try again.',
            );
          }
        },
      });
      // Optional removal
      if (profilePhoto) {
        actions.push({
          text: 'Remove Photo',
          style: 'destructive',
          onPress: async () => {
            setProfilePhoto(null);
            try {
              let firestoreMod: any = null;
              let authMod: any = null;
              try {
                firestoreMod =
                  require('@react-native-firebase/firestore').default;
              } catch {}
              try {
                authMod = require('@react-native-firebase/auth').default;
              } catch {}
              const uid = authMod?.().currentUser?.uid;
              if (firestoreMod && uid)
                await firestoreMod()
                  .doc(`users/${uid}`)
                  .set({ userPhoto: null }, { merge: true });
            } catch {}
          },
        });
      }
      actions.push({ text: 'Cancel', style: 'cancel' });
      if (actions.length > 1)
        showOceanDialog('Profile Photo', 'Update your avatar', actions);
    } catch {}
  };
                    
  // Bridge settings (Data Saver)
type BridgeSettings = {
    dataSaverDefaultOnCell: boolean;
    wifiOnlyHD: boolean;
    autoplayCellular: 'off' | 'preview' | 'full';
    prefetchNext: 0 | 1 | 2 | 3;
    thumbQuality: 'lite' | 'standard' | 'high';
    cellularMaxBitrateH264: number;
    cellularMaxBitrateHEVC: number;
    cellularResolutionCap: number; // e.g., 480
    liveCellularMaxBitrate: number;
    liveLowLatencyWifi: boolean;
    liveJoinPreview: boolean;
    liveChatLite: boolean;
    animatedThumbsCell: boolean;
    audioOnlyFallback: boolean;
    cacheMaxMB: number;
    cacheTtlHours: number; // auto-purge horizon
    backgroundDataCell: boolean;
  rainEffectsEnabled: boolean;
};

type CommandCentreSection =
  | 'home'
  | 'profile'
  | 'privacy'
  | 'notifications'
  | 'performance'
  | 'appearance'
  | 'about';
                    
  const [bridge, setBridge] = useState<BridgeSettings>({
    dataSaverDefaultOnCell: true,
    wifiOnlyHD: true,
    autoplayCellular: 'preview',
    prefetchNext: 1,
    thumbQuality: 'lite',
    cellularMaxBitrateH264: 1_000_000,
    cellularMaxBitrateHEVC: 700_000,
    cellularResolutionCap: 480,
    liveCellularMaxBitrate: 700_000,
    liveLowLatencyWifi: false,
    liveJoinPreview: true,
    liveChatLite: true,
    animatedThumbsCell: false,
    audioOnlyFallback: true,
    cacheMaxMB: 200,
    cacheTtlHours: 48,
    backgroundDataCell: false,
    rainEffectsEnabled: false,
  });
  useEffect(() => {
    if (typeof bridge.rainEffectsEnabled === 'boolean') {
      setStormEffectsEnabled(bridge.rainEffectsEnabled);
    }
  }, [bridge.rainEffectsEnabled]);
  const performancePolicy = useMemo(() => {
    const cellularMode = !isWifi || dataSaver.cellular;
    const mappedResolution =
      bridge.thumbQuality === 'high'
        ? 'high'
        : bridge.thumbQuality === 'standard'
        ? 'med'
        : 'low';
    const effectiveDataSaver = dataSaver.enabled || (cellularMode && bridge.dataSaverDefaultOnCell);
    return {
      cellularMode,
      effectiveDataSaver,
      wifiOnlyDownloads: dataSaver.wifiOnlyDownloads || bridge.wifiOnlyHD,
      autoplayOnWifiOnly: dataSaver.autoplayOnWifiOnly || bridge.autoplayCellular !== 'full',
      thumbnailsOnlyInFeed:
        dataSaver.thumbnailsOnlyInFeed || bridge.autoplayCellular === 'off',
      maxResolution: dataSaver.maxResolution || mappedResolution,
      restrictHeavyTransfers:
        effectiveDataSaver && cellularMode && !bridge.backgroundDataCell,
      liveVideoBitrate: cellularMode
        ? Math.min(bridge.liveCellularMaxBitrate || 700000, effectiveDataSaver ? 420000 : 700000)
        : 1400000,
      liveDimensions: cellularMode && effectiveDataSaver
        ? { width: 640, height: 360 }
        : { width: 960, height: 540 },
      liveFrameRate: cellularMode && effectiveDataSaver ? 15 : 24,
      audioOnlyFallback: !!(bridge.audioOnlyFallback && cellularMode && effectiveDataSaver),
    };
  }, [bridge, dataSaver, isWifi]);

  const shouldUseLightVideoUpload = useMemo(
    () => !!(performancePolicy.cellularMode && performancePolicy.effectiveDataSaver),
    [performancePolicy.cellularMode, performancePolicy.effectiveDataSaver],
  );

