  const handleWaveOptionSelect = useCallback(
    async (selectedOption: WaveOptionItem) => {
      if (!waveOptionsTarget) return;
      const isOwnPost = !!waveOptionsTarget.ownerUid && waveOptionsTarget.ownerUid === myUid;
      const entry =
        getWaveOptionMenu(isOwnPost, t).find(item => item.key === selectedOption.key) ||
        selectedOption;
      setWaveOptionsTarget(null);
      const waveLink = `aqualink://wave/${encodeURIComponent(waveOptionsTarget.id)}`;

      const copyWaveLink = async () => {
        try {
          let clipboardModule: any = null;
          try {
            clipboardModule = require('@react-native-clipboard/clipboard');
          } catch {}
          const setString =
            clipboardModule?.default?.setString || clipboardModule?.setString;
          if (typeof setString === 'function') {
            setString(waveLink);
            notifySuccess(t('feed.linkCopied'));
            return;
          }
        } catch {}
        Alert.alert(t('feed.copyLinkTitle'), waveLink);
      };

      const openEditPostComposer = () => {
        const target = waveOptionsTarget;
        const targetMediaItems = Array.isArray(target.mediaItems)
          ? target.mediaItems.filter(item => !!item?.uri)
          : [];
        const singleVisualMedia =
          targetMediaItems.length === 1
            ? targetMediaItems[0]
            : target.media?.uri
            ? target.media
            : null;
        const hasMedia =
          !!target.media?.uri ||
          targetMediaItems.length > 0 ||
          !!target.audio?.uri ||
          String(target.postType || '').toLowerCase() === 'audio' ||
          String(target.postType || '').toLowerCase() === 'document';
        setEditingWave(target);
        if (!hasMedia) {
          setReturnToMakeWaves(false);
          setShowMakeWaves(false);
          setCapturedMedia(null);
          setAttachedAudio(null);
          setUnifiedPostText(target.captionText || '');
          setUnifiedPostMediaItems([]);
          setUnifiedPostAudio(null);
          setUnifiedPostError(null);
          setUnifiedPostProgress(null);
          setNeedsUnifiedCaptionReview(false);
          setShowUnifiedPostModal(true);
          return;
        }
        if (
          singleVisualMedia &&
          (isImageAsset(singleVisualMedia) || isVideoAsset(singleVisualMedia)) &&
          !target.audio?.uri
        ) {
          setShowMakeWaves(false);
          setUnifiedPostMediaItems([]);
          setUnifiedPostAudio(null);
          setCapturedMedia(singleVisualMedia);
          setCapturedMediaEdits(target.mediaEdits || defaultMediaEdits);
          setWaveCaption(target.captionText || '');
          setTextComposerText(target.captionText || '');
          return;
        }
        setUnifiedPostText(target.captionText || '');
        setUnifiedPostMediaItems(
          targetMediaItems.length > 0
            ? targetMediaItems
            : target.media?.uri
            ? [target.media]
            : [],
        );
        setUnifiedPostAudio(target.audio || null);
        setUnifiedPostError(null);
        setUnifiedPostProgress(null);
        setNeedsUnifiedCaptionReview(false);
        setReturnToMakeWaves(false);
        setShowUnifiedPostModal(true);
      };
                    
      // Handle other wave options
      if (entry?.key === 'edit') {
        openEditPostComposer();
        return;
      }

      if (entry?.key === 'delete') {
        deleteWave(waveOptionsTarget.id);
        return;
      }

      if (entry?.key === 'copy_link') {
        await copyWaveLink();
        return;
      }

      if (entry?.key === 'save') {
        if (isSavingWave) return;
        setIsSavingWave(true);
                    
        try {
          // Try backend endpoint first
          let downloadUrl: string | null = null;
                    
          try {
            const cfgLocal = (() => {
              try {
                return require('./liveConfig');
              } catch {
                return null;
              }
            })();
            const backendBase: string =
              (cfgLocal &&
                (cfgLocal.BACKEND_BASE_URL ||
                  cfgLocal.USER_MGMT_ENDPOINT_BASE ||
                  cfgLocal.USER_MANAGEMENT_BASE_URL)) ||
              '';
                    
            if (backendBase) {
              const resp = await fetch(`${backendBase}/wave/download`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                  waveId: waveOptionsTarget.id,
                  mergeCaption: true,
                  captionText: String(waveOptionsTarget.captionText || ''),
                }),
              });
                    
              if (resp.ok) {
                const data = await resp.json();
                downloadUrl = data.downloadUrl;
              }
            }
          } catch {}
                    
          // Fallback: Try to get download URL directly from Firestore + Storage
          if (!downloadUrl) {
            try {
              let firestoreMod: any = null;
              let storageMod: any = null;
              try {
                firestoreMod =
                  require('@react-native-firebase/firestore').default;
              } catch {}
              try {
                storageMod = require('@react-native-firebase/storage').default;
              } catch {}
                    
              if (firestoreMod && storageMod) {
                const waveDoc = await firestoreMod()
                  .collection('waves')
                  .doc(waveOptionsTarget.id)
                  .get();
                const waveData = waveDoc.data() || {};
                const mediaPath =
                  waveData.mediaPath ||
                  waveData.playbackUrl ||
                  waveData.mediaUrl;
                    
                if (mediaPath) {
                  // If it's a full URL, use it directly
                  if (
                    mediaPath.startsWith('http://') ||
                    mediaPath.startsWith('https://')
                  ) {
                    downloadUrl = mediaPath;
                  } else {
                    // Otherwise, get download URL from Storage
                    downloadUrl = await storageMod()
                      .ref(mediaPath)
                      .getDownloadURL();
                  }
                }
              }
            } catch (storageError) {
              console.error('Storage download error:', storageError);
            }
          }
                    
          if (downloadUrl) {
            const mediaTypeLower = String(waveOptionsTarget.mediaType || '').toLowerCase();
            const inferredExt = (() => {
              const urlLower = String(downloadUrl).toLowerCase();
              if (urlLower.includes('.png')) return 'png';
              if (urlLower.includes('.webp')) return 'webp';
              if (urlLower.includes('.jpg') || urlLower.includes('.jpeg')) return 'jpg';
              if (urlLower.includes('.mov')) return 'mov';
              if (urlLower.includes('.m4v')) return 'm4v';
              if (urlLower.includes('.mp4')) return 'mp4';
              if (mediaTypeLower.includes('image') || mediaTypeLower.includes('photo')) return 'jpg';
              return 'mp4';
            })();
            const safeBase = String(
              waveOptionsTarget.captionText ||
                waveOptionsTarget.authorName ||
                waveOptionsTarget.id ||
                'momo',
            )
              .trim()
              .replace(/[^A-Za-z0-9._-]+/g, '_')
              .replace(/^_+|_+$/g, '')
              .slice(0, 42) || 'momo';
            const fileName = `CMEE_${safeBase}_${Date.now()}.${inferredExt}`;
            if (
              !(await ensureNetworkActionAllowed('download', {
                label: 'save this post',
                kind: inferTransferKind({
                  mimeType: waveOptionsTarget.mediaType,
                  fileName,
                  url: downloadUrl,
                }),
                allowOnCellular: true,
              }))
            ) {
              return;
            }
            const ok = await downloadWave(
              String(waveOptionsTarget.id),
              String(downloadUrl),
              fileName,
            );
            if (!ok) {
              return;
            }
          } else {
            throw new Error('Could not retrieve download link');
          }
        } catch (error: any) {
          const errorMsg =
            error?.message || 'Unable to prepare the download right now.';
          showOceanDialog(
            t('feed.saveFailedTitle'),
            errorMsg || t('feed.saveFailedBody'),
          );
        } finally {
          setIsSavingWave(false);
        }
        return;
      }
                    
      if (entry?.key === 'share') {
        try {
          const subject = waveOptionsTarget.captionText
            ? `"${waveOptionsTarget.captionText}"`
            : t('feed.defaultSubject');
          await Share.share({
            title: t('feed.shareTitle'),
            message: t('feed.shareBody', {
              subject,
              link: waveLink,
            }),
          });
        } catch {}
        return;
      }

      if (entry?.key === 'fleet_deck') {
        setShowFleetDeck(true);
        return;
      }
      
      if (selectedOption.label === 'Gem') {
        setShowGemDropdown(true);
        return;
      }
      
      if (entry?.key === 'report') {
        Alert.alert(
          entry?.label || selectedOption.label,
          entry?.description || t('feed.reportQueued'),
        );
        return;
      }
                    
      Alert.alert(
        entry?.label || selectedOption.label,
        entry?.description || t('feed.comingSoon'),
      );
    },
    [waveOptionsTarget, myUid, notifySuccess, isSavingWave, t],
  );
  const [isBottomBarExpanded, setIsBottomBarExpanded] = useState(false);
