  const [showInviteModal, setShowInviteModal] = useState(false);
  const [inviteQuery, setInviteQuery] = useState('');
  const [inviteResults, setInviteResults] = useState<
    Array<{ uid: string; name?: string; email?: string; photo?: string }>
  >([]);
  const [selectedInviteUid, setSelectedInviteUid] = useState<string | null>(null);
  const [inviteBusy, setInviteBusy] = useState(false);
  const [hereNowInviteSendingByUid, setHereNowInviteSendingByUid] = useState<
    Record<string, boolean>
  >({});
  const [hiddenHereNowInvitees, setHiddenHereNowInvitees] = useState<Set<string>>(
    new Set(),
  );
                    
  const inviteCoHost = async () => {
    setInviteQuery('');
    setInviteResults([]);
    setSelectedInviteUid(null);
    setShowInviteModal(true);
  };
                    
  const searchInviteCandidates = async () => {
    setInviteBusy(true);
    try {
      let firestoreMod: any = null;
      try {
        firestoreMod = require('@react-native-firebase/firestore').default;
      } catch {}
      const q = (inviteQuery || '').trim();
      if (!q || !firestoreMod) {
        setInviteResults([]);
        setInviteBusy(false);
        return;
      }
      // Fetch a batch of users for fuzzy search
      let users: Array<{ uid: string; name?: string; email?: string; photo?: string }> = [];
      try {
        const snap = await firestoreMod()
          .collection('users')
          .limit(100)
          .get();
        snap.forEach((d: any) => {
          const data = d.data();
          users.push({
            uid: d.id,
            name: data?.displayName,
            email: data?.email || null,
            photo: data?.photoURL || null,
          });
        });
      } catch {}
      // Fuzzy search using Fuse.js
      const fuse = new Fuse(users, {
        keys: ['name', 'email', 'uid'],
        threshold: 0.4,
        minMatchCharLength: 2,
      });
      const results = fuse.search(q).map(r => r.item).slice(0, 10);
      setInviteResults(results);
      setSelectedInviteUid(results[0]?.uid || null);
    } catch (e) {
      setInviteResults([]);
      setSelectedInviteUid(null);
    } finally {
      setInviteBusy(false);
    }
  };
                    
  const inviteUserToDrift = async (targetUid: string) => {
    const me = auth?.()?.currentUser;
    if (!me) throw new Error('Sign in required');
    const sendCrewInvitation =
      functions().httpsCallable('sendCrewInvitation');
    const result = await sendCrewInvitation({
      toUid: targetUid,
      crewId: liveDocId || 'default-crew',
      crewName: liveTitle || 'Live Session',
      message: `Join my live ${liveTitle || 'session'}`,
    });
    const status = String(result?.data?.status || '').trim().toLowerCase();
    if (status !== 'sent') {
      throw new Error(
        `sendCrewInvitation returned status=${status || 'unknown'}`,
      );
    }
    return true;
  };
                    
  const sendInviteTo = async (
    to: { uid?: string; name?: string } | string,
    options?: { silent?: boolean; requireFeedPanel?: boolean },
  ): Promise<boolean> => {
    const formatInviteDebugError = (err: any): string => {
      try {
        const codeRaw =
          err?.code ||
          err?.details?.code ||
          err?.errorInfo?.code ||
          err?.name ||
          '';
        const messageRaw =
          err?.message ||
          err?.details?.message ||
          err?.errorInfo?.message ||
          '';
        const code = String(codeRaw || '').trim();
        const message = String(messageRaw || '').trim();
        if (code && message) return `${code}: ${message}`;
        if (code) return code;
        if (message) return message;
        try {
          return JSON.stringify(err);
        } catch {
          return String(err || 'Unknown invite error');
        }
      } catch {
        return 'Unknown invite error';
      }
    };

    let toUid = '';
    if (typeof to === 'string') {
      toUid = to.trim().replace(/^@/, '');
    } else if (to?.uid) {
      toUid = to.uid;
    }
                    
    if (!toUid) {
      Alert.alert('Error', 'Invalid user ID');
      return false;
    }
                    
    setInviteBusy(true);
    try {
      const me = auth?.()?.currentUser;
      if (!me?.uid) {
        throw new Error('Sign in required');
      }
      const callerName = String(
        me.displayName ||
          (me.email ? String(me.email).split('@')[0] : '') ||
          hostName ||
          'Skipper',
      ).trim();
      const senderPhoto = me.photoURL || null;
      let cfgLocal: any = null;
      try {
        cfgLocal = require('./liveConfig');
      } catch {}
      const fixedLiveChannel = String(
        liveChannel || cfgLocal?.AGORA_CHANNEL_NAME || 'AqualinkSharedLive',
      )
        .trim()
        .replace(/[^A-Za-z0-9_]/g, '_')
        .slice(0, 64);
      const fixedLiveToken = String(
        liveToken || '',
      ).trim();
      let inboxInviteWritten = false;
      let callableInviteSent = false;
      let inviteStatusWritten = false;
      let fallbackMentionWritten = false;
      let fallbackPingWritten = false;
      let deliveryMode: 'none' | 'inbox' | 'fallback' = 'none';
      let inviteSentToastShown = false;
      let lastErr: any = null;
      let inviteDocId: string | null = null;
      const directCallId: string | null = null;
      const directCallChannel: string | null = null;
      const directCallType: DirectCallMode = 'video';
      const computedExpiry = Date.now() + LIVE_INVITE_EXPIRY_MS;

      try {
        const liveInvitesRef = firestore().collection(
          `users/${toUid}/live_invites`,
        );
        let existingPending: any = null;
        if (liveDocId) {
          try {
            existingPending = await liveInvitesRef
              .where('status', '==', 'pending')
              .where('fromUid', '==', me.uid)
              .where('liveId', '==', liveDocId)
              .limit(1)
              .get();
          } catch {
            existingPending = null;
          }
        }
        // Invite-only flow: do not create direct call sessions here.

        const invitePayload = {
          liveId: liveDocId || null,
          liveChannel: fixedLiveChannel || null,
          liveToken: fixedLiveToken || null,
          liveTitle: liveTitle || 'Live Session',
          fromUid: me.uid,
          fromName: callerName,
          fromPhoto: senderPhoto,
          directCallId: directCallId || null,
          callType: directCallType,
          directCallChannel: directCallChannel || null,
          status: 'pending',
          createdAt: firestore.FieldValue.serverTimestamp(),
          expiresAtMs: computedExpiry,
        };
        if (existingPending && !existingPending.empty) {
          const ref = existingPending.docs[0].ref;
          inviteDocId = existingPending.docs[0].id;
          await ref.set(invitePayload, { merge: true });
        } else {
          const inviteRef = await liveInvitesRef.add(invitePayload);
          inviteDocId = inviteRef.id;
        }
        inboxInviteWritten = true;

        if (!options?.silent) {
          Alert.alert('Invite Sent', 'Invitation sent to feed badge.');
          setShowInviteModal(false);
          inviteSentToastShown = true;
        }
      } catch (err) {
        console.warn('[INVITE DEBUG] inbox invite write failed', err);
        lastErr = err;
      }

      // Non-blocking: do not delay user feedback on callable side-channel.
      inviteUserToDrift(toUid).catch(err => {
        console.warn('[INVITE DEBUG] callable sendCrewInvitation failed', err);
      });

      try {
        await firestore()
          .collection(`users/${toUid}/mentions`)
          .add({
            type: 'live_invite',
            text: `${callerName} invited you to join ${liveTitle || 'Drift Expo'}`,
            fromUid: me.uid,
            fromName: callerName,
            fromPhoto: senderPhoto,
            route: 'Pings',
            liveId: liveDocId || '',
            liveTitle: liveTitle || 'Drift Expo',
            liveChannel: fixedLiveChannel || null,
            liveToken: fixedLiveToken || null,
            directCallId: directCallId || null,
            directCallChannel: directCallChannel || null,
            callType: directCallType,
            status: 'pending',
            expiresAtMs: computedExpiry,
            createdAt: firestore.FieldValue.serverTimestamp(),
          });
        fallbackMentionWritten = true;
      } catch (err) {
        console.warn('[INVITE DEBUG] mention fallback write failed', err);
        lastErr = err;
      }
      try {
        await firestore()
          .collection(`users/${toUid}/pings`)
          .add({
            type: 'live_invite',
            text: `${callerName} invited you to join ${liveTitle || 'Drift Expo'}`,
            fromUid: me.uid,
            fromName: callerName,
            fromPhoto: senderPhoto,
            liveId: liveDocId || '',
            liveTitle: liveTitle || 'Drift Expo',
            liveChannel: fixedLiveChannel || null,
            liveToken: fixedLiveToken || null,
            directCallId: directCallId || null,
            directCallChannel: directCallChannel || null,
            callType: directCallType,
            status: 'pending',
            read: false,
            expiresAtMs: computedExpiry,
            createdAt: firestore.FieldValue.serverTimestamp(),
          });
        fallbackPingWritten = true;
      } catch (err) {
        console.warn('[INVITE DEBUG] ping fallback write failed', err);
        lastErr = err;
      }

      if (liveDocId && inviteDocId) {
        firestore()
          .collection(`live/${liveDocId}/invite_status`)
          .doc(toUid)
          .set(
            {
              uid: toUid,
              name:
                typeof to === 'string'
                  ? toUid
                  : to?.name || toUid,
              status: 'pending',
              inviteId: inviteDocId,
              fromUid: me.uid,
              liveId: liveDocId,
              liveChannel: fixedLiveChannel || null,
              token: fixedLiveToken || null,
              directCallId: directCallId || null,
              callType: directCallType,
              directCallChannel: directCallChannel || null,
              expiresAtMs: computedExpiry,
              updatedAt: firestore.FieldValue.serverTimestamp(),
            },
            { merge: true },
          )
          .then(() => {
            inviteStatusWritten = true;
          })
          .catch(() => {});
      }

      const requireFeedPanel = options?.requireFeedPanel !== false;
      const fallbackWorked =
        callableInviteSent ||
        inviteStatusWritten ||
        fallbackMentionWritten ||
        fallbackPingWritten;
      if (inboxInviteWritten || (!requireFeedPanel && fallbackWorked)) {
        deliveryMode = inboxInviteWritten ? 'inbox' : 'fallback';
        if (!options?.silent && !inviteSentToastShown) {
          Alert.alert(
            'Invite Sent',
            deliveryMode === 'inbox'
              ? 'Invitation sent to feed badge.'
              : 'Invite delivered as notification. Feed badge may not appear immediately.',
          );
          setShowInviteModal(false);
        }
        return true;
      } else {
        console.warn('[INVITE DEBUG] no invite channel succeeded', {
          inboxInviteWritten,
          callableInviteSent,
          inviteStatusWritten,
          fallbackMentionWritten,
          fallbackPingWritten,
          requireFeedPanel,
        });
        throw (
          lastErr ||
          new Error(
            requireFeedPanel
              ? 'Feed badge delivery failed (users/{uid}/live_invites write did not succeed).'
              : 'No invite channel succeeded',
          )
        );
      }
    } catch (error) {
      const debugInfo = formatInviteDebugError(error);
      const debugInfoUpper = debugInfo.toUpperCase();
      const hasInternal = debugInfoUpper.includes('INTERNAL');
      console.warn('[INVITE DEBUG] sendInviteTo failed', {
        toUid,
        toType: typeof to === 'string' ? 'string' : 'object',
        liveDocId: liveDocId || null,
        liveChannel: liveChannel || null,
        debugInfo,
        rawError: error,
      });
      Alert.alert(
        'Invite Failed',
        hasInternal
          ? `INTERNAL error while sending invite.\n\nDebug: ${debugInfo}`
          : `Failed to send invite.\n\nDebug: ${debugInfo}`,
      );
      return false;
    } finally {
      setInviteBusy(false);
    }
    return false;
  };

  const sendUnifiedDriftInvite = async (
    target: { uid: string; name?: string },
    options?: { silent?: boolean },
  ): Promise<boolean> => {
    if (!target?.uid) return false;
    return await sendInviteTo(
      { uid: target.uid, name: target.name || target.uid },
      { silent: options?.silent, requireFeedPanel: true },
    );
  };

