/* ----------------------- Auth Screens ------------------------- */
function SignUpScreen({ navigation }: any) {
  const { t } = useAppLanguage();
  const [email, setEmail] = useState('');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [agreedToTerms, setAgreedToTerms] = useState(false);
                    
  const validatePassword = (p: string) => {
    if (p.length < 8 || p.length > 64) return false;
    const checks = [
      /[a-z]/.test(p), // lowercase
      /[A-Z]/.test(p), // uppercase
      /\d/.test(p), // number
      /[^a-zA-Z0-9]/.test(p), // symbol
    ];
    return checks.filter(Boolean).length >= 3;
  };
                    
  const signUp = async () => {
    const trimmedEmail = email.trim();
    const trimmedUsername = normalizeUniqueUsername(username);
                    
    if (!trimmedEmail || !trimmedUsername || !password || !confirmPassword) {
      Alert.alert(t('alert.missingInfoTitle'), t('alert.missingInfoBody'));
      return;
    }
    if (trimmedUsername.length < 3) {
      Alert.alert(
        t('alert.chooseUsernameTitle'),
        t('alert.chooseUsernameBody'),
      );
      return;
    }
    
    // Check if it's an email or phone number
    const isEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmedEmail);
    const isPhone = /^[\+]?[1-9][\d]{0,15}$/.test(trimmedEmail.replace(/[\s\-\(\)]/g, ''));
    
    if (!isEmail && !isPhone) {
      Alert.alert(t('alert.invalidInputTitle'), t('alert.invalidInputBody'));
      return;
    }
    
    if (!validatePassword(password)) {
      Alert.alert(t('alert.weakPasswordTitle'), t('alert.weakPasswordBody'));
      return;
    }
    if (password !== confirmPassword) {
      Alert.alert(
        t('alert.passwordMismatchTitle'),
        t('alert.passwordMismatchBody'),
      );
      return;
    }
    if (!agreedToTerms) {
      Alert.alert(
        t('alert.agreementRequiredTitle'),
        t('alert.agreementRequiredBody'),
      );
      return;
    }
    try {
      let userCredential;
      
      if (isEmail) {
        // Create user with email
        userCredential = await auth().createUserWithEmailAndPassword(
          trimmedEmail,
          password,
        );
      } else {
        // Create user with phone number - proper implementation
        // Ensure phone number has country code
        let formattedPhone = trimmedEmail;
        if (!formattedPhone.startsWith('+')) {
          // If no country code, assume US (+1) - you may want to make this configurable
          formattedPhone = '+1' + formattedPhone.replace(/\D/g, '');
        }
        
        console.log('Attempting phone auth with:', formattedPhone);
        
        try {
          const confirmation = await auth().signInWithPhoneNumber(formattedPhone);
          
          // Show verification code input dialog
          Alert.prompt(
            'Phone Verification',
            `Enter the 6-digit verification code sent to ${formattedPhone}:`,
            [
              {
                text: 'Cancel',
                style: 'cancel',
              },
              {
                text: 'Verify',
                onPress: async (code) => {
                  if (!code || code.length !== 6) {
                    Alert.alert('Invalid Code', 'Please enter a valid 6-digit verification code.');
                    return;
                  }
                  
                  try {
                    const result = await confirmation.confirm(code);
                    
                    if (result.user) {
                      const firestoreMod = require('@react-native-firebase/firestore').default;
                      try {
                        await reserveUniqueUsername(result.user.uid, trimmedUsername);
                      } catch (usernameError: any) {
                        await result.user.delete().catch(() => {});
                        if (String(usernameError?.message || '').includes('username-taken')) {
                          Alert.alert('Username Taken', 'That username is already in use. Try another one.');
                        } else {
                          Alert.alert('Sign Up Unavailable', 'We could not finish account setup right now. Please try again.');
                        }
                        return;
                      }
                      await firestoreMod().collection('users').doc(result.user.uid).set({
                        phoneNumber: formattedPhone,
                        createdAt: firestoreMod.FieldValue.serverTimestamp(),
                      }, { merge: true });
                      await result.user.updateProfile({
                        displayName: trimmedUsername,
                      });
                      
                      // Mark authentication as completed so user stays signed in
                      await AsyncStorage.setItem('auth_completed', 'true');
                      
                      Alert.alert(
                        t('alert.successTitle'),
                        t('alert.accountCreatedBody'),
                      );
                    }
                  } catch (verifyError: any) {
                    console.error('Verification error:', verifyError);
                    Alert.alert(
                      'Verification Failed',
                      verifyError?.message || 'Invalid verification code. Please try again.'
                    );
                  }
                },
              },
            ],
            'plain-text'
          );
        } catch (phoneError: any) {
          console.error('Phone auth error:', phoneError);
          
          // Handle specific Firebase Auth errors
          if (phoneError.code === 'auth/invalid-phone-number') {
            Alert.alert('Invalid Phone Number', 'Please enter a valid phone number with country code (e.g., +1234567890).');
          } else if (phoneError.code === 'auth/missing-phone-number') {
            Alert.alert('Missing Phone Number', 'Please enter your phone number.');
          } else if (phoneError.code === 'auth/too-many-requests') {
            Alert.alert('Too Many Requests', 'Too many verification attempts. Please try again later.');
          } else if (phoneError.code === 'auth/operation-not-allowed') {
            Alert.alert(
              'Phone Sign Up Unavailable',
              'Phone sign up is not available right now. Please try email instead.'
            );
          } else if (phoneError.code === 'auth/missing-client-identifier') {
            Alert.alert(
              'Phone Verification Unavailable',
              'Phone verification is not ready right now. Please try again later or use email.'
            );
          } else if (phoneError.code === 'auth/invalid-verification-code') {
            Alert.alert('Invalid Code', 'The verification code is invalid. Please try again.');
          } else if (phoneError.code === 'auth/code-expired') {
            Alert.alert('Code Expired', 'The verification code has expired. Please request a new one.');
          } else {
            Alert.alert(
              'Phone Verification Failed',
              'We could not send the verification code right now. Please check your network and try again.'
            );
          }
        }
        return; // Don't proceed with the rest of the signup flow
      }
      
      if (userCredential.user) {
        const firestoreMod = require('@react-native-firebase/firestore').default;
        try {
          await reserveUniqueUsername(userCredential.user.uid, trimmedUsername);
        } catch (usernameError: any) {
          await userCredential.user.delete().catch(() => {});
          if (String(usernameError?.message || '').includes('username-taken')) {
            Alert.alert('Username Taken', 'That username is already in use. Try another one.');
          } else {
            Alert.alert('Sign Up Unavailable', 'We could not finish account setup right now. Please try again.');
          }
          return;
        }
        await firestoreMod().collection('users').doc(userCredential.user.uid).set({
          email: isEmail ? trimmedEmail : null,
          phoneNumber: isPhone ? trimmedEmail : null,
          createdAt: firestoreMod.FieldValue.serverTimestamp(),
        }, { merge: true });
        await userCredential.user.updateProfile({
          displayName: trimmedUsername,
        });
        
        // Mark authentication as completed so user stays signed in
        await AsyncStorage.setItem('auth_completed', 'true');
      }
    } catch (e: any) {
      if (e.code === 'auth/email-already-in-use') {
        Alert.alert(
          'Email Already in Use',
          'This email is already registered. If you created an account before, please sign in instead. If you\'re sure this email hasn\'t been used, try clearing app data or use a different email.',
          [
            { text: 'Try Sign In', onPress: () => navigation.replace('SignIn') },
            { text: 'Use Different Email', style: 'cancel' }
          ]
        );
      } else {
        const signUpMessage =
          String(e?.code || '').includes('network')
            ? t('alert.noInternetBody')
            : t('alert.signUpFailedBody');
        Alert.alert(t('alert.signUpFailedTitle'), signUpMessage);
      }
    }
  };
                    
  return (
    <View style={authStyles.screen}>
      <AuthBackground />
      <KeyboardAvoidingView
        behavior={Platform.select({ ios: 'padding', android: undefined })}
        style={{ flex: 1, justifyContent: 'center' }}
      >
        <ScrollView showsVerticalScrollIndicator={false}>
          <Text style={authStyles.title}>{t('auth.signupTitle')}</Text>
                    
          <Field
            label={t('auth.email')}
            value={email}
            onChangeText={setEmail}
            keyboardType="email-address"
          />
          <Field
            label={t('auth.username')}
            value={username}
            onChangeText={setUsername}
          />
          <Field
            label={t('auth.password')}
            value={password}
            onChangeText={setPassword}
            secureTextEntry
          />
          <Text
            style={{
              color: 'rgba(255,255,255,0.7)',
              fontSize: 12,
              marginTop: -8,
              marginBottom: 8,
            }}
          >
            {t('auth.passwordHint')}
          </Text>
          <Field
            label={t('auth.confirmPassword')}
            value={confirmPassword}
            onChangeText={setConfirmPassword}
            secureTextEntry
          />
                    
          <View
            style={{
              flexDirection: 'row',
              alignItems: 'center',
              marginVertical: 12,
            }}
          >
            <Pressable
              onPress={() => setAgreedToTerms(!agreedToTerms)}
              style={({ pressed }) => [
                {
                  width: 24,
                  height: 24,
                  borderWidth: 1,
                  borderColor: 'white',
                  borderRadius: 4,
                  marginRight: 12,
                  alignItems: 'center',
                  justifyContent: 'center',
                },
                pressed && {
                  opacity: 0.8,
                  transform: [{ scale: 0.9 }],
                }
              ]}
              hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }}
            >
              {agreedToTerms && (
                <Text
                  style={{ color: 'white', fontSize: 16, fontWeight: 'bold' }}
                >
                  ?
                </Text>
              )}
            </Pressable>
            <Text style={{ color: 'white', flex: 1 }}>
              {t('auth.agreePrefix')}{' '}
              <Text
                style={{ color: '#2196F3', textDecorationLine: 'underline' }}
                onPress={() =>
                  Alert.alert(t('alert.termsTitle'), t('alert.termsBody'))
                }
              >
                {t('auth.terms')}
              </Text>{' '}
              and{' '}
              <Text
                style={{ color: '#2196F3', textDecorationLine: 'underline' }}
                onPress={() =>
                  Alert.alert(t('alert.privacyTitle'), t('alert.privacyBody'))
                }
              >
                {t('auth.privacy')}
              </Text>
              .
            </Text>
          </View>
                    
          <AuthButton title={t('auth.signup')} onPress={signUp} />
                    
          <Pressable
            onPress={() => navigation.replace('SignIn')}
            style={({ pressed }) => [
              { marginTop: 14 },
              pressed && { opacity: 0.7 }
            ]}
            hitSlop={{ top: 5, bottom: 5, left: 5, right: 5 }}
          >
            <Text style={authStyles.link}>{t('auth.alreadyHaveAccount')}</Text>
          </Pressable>
        </ScrollView>
      </KeyboardAvoidingView>
    </View>
  );
}
                    
function SignInScreen({ navigation }: any) {
  const { t } = useAppLanguage();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
                    
  const signIn = async () => {
    const trimmedEmail = email.trim();
    
    if (!trimmedEmail || !password) {
      Alert.alert(t('alert.missingInfoTitle'), t('alert.missingInfoBody'));
      return;
    }
    
    // Check if it's an email or phone number
    const isEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmedEmail);
    const isPhone = /^[\+]?[1-9][\d]{0,15}$/.test(trimmedEmail.replace(/[\s\-\(\)]/g, ''));
    
    if (!isEmail && !isPhone) {
      Alert.alert(t('alert.invalidInputTitle'), t('alert.invalidInputBody'));
      return;
    }
    
    try {
      let userCredential;
      
      if (isEmail) {
        // Sign in with email
        userCredential = await auth().signInWithEmailAndPassword(
          trimmedEmail,
          password,
        );
      } else {
        // Sign in with phone number - this would require phone auth flow
        Alert.alert(
          t('alert.phoneSignInTitle'),
          t('alert.phoneSignInBody'),
        );
        return;
      }
      
      if (userCredential.user) {
        // Mark authentication as completed so user stays signed in
        await AsyncStorage.setItem('auth_completed', 'true');
        console.log('User signed in successfully:', userCredential.user.uid);
      }
    } catch (e: any) {
      if (e.code === 'auth/user-not-found') {
        Alert.alert(
          t('alert.accountNotFoundTitle'),
          t('alert.accountNotFoundBody'),
          [
            { text: t('auth.signup'), onPress: () => navigation.replace('SignUp') },
            { text: 'Try Again', style: 'cancel' }
          ]
        );
      } else if (e.code === 'auth/wrong-password') {
        Alert.alert(
          t('alert.incorrectPasswordTitle'),
          t('alert.incorrectPasswordBody'),
        );
      } else {
        const signInMessage =
          String(e?.code || '').includes('network')
            ? t('alert.noInternetBody')
            : t('alert.signUpFailedBody');
        Alert.alert(t('alert.signInFailedTitle'), signInMessage);
      }
    }
  };
                    
  const resetPassword = async () => {
    const trimmedEmail = email.trim();
    if (!trimmedEmail) {
      Alert.alert(t('alert.missingEmailTitle'), t('alert.missingEmailBody'));
      return;
    }
                    
    try {
      await auth().sendPasswordResetEmail(trimmedEmail);
      Alert.alert(
        t('alert.resetLinkSentTitle'),
        t('alert.resetLinkSentBody'),
      );
    } catch (e: any) {
      const resetMessage =
        String(e?.code || '').includes('network')
          ? t('alert.noInternetBody')
          : t('alert.signUpFailedBody');
      Alert.alert(t('alert.resetFailedTitle'), resetMessage);
    }
  };
                    
  return (
    <View style={authStyles.screen}>
      <AuthBackground />
      <KeyboardAvoidingView
        behavior={Platform.select({ ios: 'padding', android: undefined })}
        style={{ flex: 1, justifyContent: 'center' }}
      >
        <Text style={authStyles.title}>{t('auth.signinTitle')}</Text>
                    
        <Field
          label={t('auth.emailOrPhone')}
          value={email}
          onChangeText={setEmail}
          keyboardType="email-address"
        />
        <Field
          label={t('auth.password')}
          value={password}
          onChangeText={setPassword}
          secureTextEntry
        />
                    
        <Pressable 
          onPress={resetPassword} 
          style={({ pressed }) => [
            { marginTop: 6 },
            pressed && { opacity: 0.7 }
          ]}
          hitSlop={{ top: 5, bottom: 5, left: 5, right: 5 }}
        >
          <Text style={authStyles.link}>{t('auth.forgotPassword')}</Text>
        </Pressable>
                    
        <View style={{ marginTop: 4 }}>
          <AuthButton title={t('auth.signin')} onPress={signIn} />
        </View>
                    
        <Pressable
          onPress={() => navigation.replace('SignUp')}
          style={({ pressed }) => [
            { marginTop: 14 },
            pressed && { opacity: 0.7 }
          ]}
          hitSlop={{ top: 5, bottom: 5, left: 5, right: 5 }}
        >
          <Text style={authStyles.link}>{t('auth.noAccount')}</Text>
        </Pressable>
      </KeyboardAvoidingView>
    </View>
  );
}
                    
function WelcomeAnimationScreen({ navigation }: any) {
  const { t } = useAppLanguage();
  const isMounted = React.useRef(true);
  const bounceAnim = React.useRef(new Animated.Value(0)).current;
  const fadeAnim = React.useRef(new Animated.Value(0)).current;
                    
  React.useEffect(() => {
    Animated.spring(bounceAnim, {
      toValue: 1,
      friction: 3,
      tension: 40,
      useNativeDriver: true,
    }).start();
    Animated.timing(fadeAnim, {
      toValue: 1,
      duration: 650,
      useNativeDriver: true,
    }).start();

    const timer = setTimeout(() => {
      if (isMounted.current) {
        navigation.replace('AppHome');
      }
    }, 5200);
                    
    return () => {
      isMounted.current = false;
      clearTimeout(timer);
    };
  }, [bounceAnim, fadeAnim, navigation]);
                    
  const bounceTranslateY = bounceAnim.interpolate({
    inputRange: [0, 0.5, 1],
    outputRange: [50, -10, 0],
  });
                    
  const handleSkip = () => {
    if (isMounted.current) {
      navigation.replace('AppHome');
    }
  };
                    
  return (
    <Pressable
      style={{
        flex: 1,
        backgroundColor: '#07111B',
        justifyContent: 'center',
        alignItems: 'center',
        paddingHorizontal: 26,
      }}
      onPress={handleSkip}
    >
      <Animated.View
        style={{
          transform: [{ translateY: bounceTranslateY }],
          opacity: fadeAnim,
          alignItems: 'center',
        }}
      >
        <Image
          source={require('./assets/cmee_logo_final.png')}
          style={{
            width: 156,
            height: 156,
            resizeMode: 'contain',
            marginBottom: 22,
          }}
        />
        <Text
          style={{
            maxWidth: 280,
            color: '#C7EAFE',
            fontSize: 16,
            lineHeight: 22,
            fontWeight: '700',
            textAlign: 'center',
          }}
        >
          {t('welcome.subtitle')}
        </Text>
      </Animated.View>
    </Pressable>
  );
}
                    
function PostDetailScreen({ route, navigation }: any) {
  const { post } = route.params;
  const [playbackTime, setPlaybackTime] = useState(0);
  const [playbackDuration, setPlaybackDuration] = useState(0);
  const isFocused = useIsFocused();
  const [isFollowing, setIsFollowing] = useState(false);
  const [currentUserId, setCurrentUserId] = useState<string | null>(null);
  const [reach, setReach] = useState(0);
  
  // Record video reach function
  const recordVideoReach = async (postId: string) => {
    try {
      const recordReachFn = functions().httpsCallable('recordVideoReach');
      const result = await recordReachFn({ postId });
      return result.data;
    } catch (error) {
      console.error('Record Video Reach function error:', error);
      // Don't crash - just return a safe response
      return { success: false, error: 'Function not available' };
    }
  };
  
  // Get current user
  useEffect(() => {
    const getCurrentUser = async () => {
      try {
        const user = auth().currentUser;
        if (user) {
          setCurrentUserId(user.uid);
          // Check if already following
          const followDoc = await firestore()
            .collection('users')
            .doc(user.uid)
            .collection('following')
            .doc(post.userId)
            .get();
          setIsFollowing(followDoc.exists);
        }
      } catch (error) {
        console.log('Error getting current user:', error);
      }
    };
    getCurrentUser();
  }, [post.userId]);
  
  // Listen to reach count changes (temporarily disabled for testing)
  useEffect(() => {
    const getReachCount = async () => {
      try {
        const doc = await firestore()
          .collection('waves')
          .doc(post.id)
          .get();
        if (doc.exists) {
          const data = doc.data();
          setReach(data?.reach || 0);
        }
      } catch (error) {
        console.log('Error getting reach count:', error);
      }
    };
    getReachCount();
  }, [post.id]);
  
  // Increment views for video posts when video loads (only if not the author)
  const incrementViews = async () => {
    if (currentUserId && currentUserId !== post.userId) {
      try {
        const firestoreMod = require('@react-native-firebase/firestore').default;
        await firestoreMod()
          .collection('waves')
          .doc(post.id)
          .update({
            reach: firestoreMod.FieldValue.increment(1)
          });
      } catch (error) {
        console.log('Error incrementing views:', error);
      }
    }
  };
  
  const handleFollow = async () => {
    if (!currentUserId || !post.userId || currentUserId === post.userId) return;
    
    try {
      const firestoreMod = require('@react-native-firebase/firestore').default;
      const authMod = require('@react-native-firebase/auth').default;
      const messagingMod = require('@react-native-firebase/messaging').default;
      
      if (isFollowing) {
        // Unfollow
        await firestoreMod()
          .collection('users')
          .doc(currentUserId)
          .collection('following')
          .doc(post.userId)
          .delete();
        await firestoreMod()
          .collection('users')
          .doc(post.userId)
          .collection('followers')
          .doc(currentUserId)
          .delete();
        setIsFollowing(false);
      } else {
        // Follow
        const followData = {
          userId: post.userId,
          followedAt: firestoreMod.Timestamp.now()
        };
        const followerData = {
          userId: currentUserId,
          followedAt: firestoreMod.Timestamp.now(),
          followerName: authMod().currentUser?.displayName || 'Anonymous Drifter'
        };
        
        await firestoreMod()
          .collection('users')
          .doc(currentUserId)
          .collection('following')
          .doc(post.userId)
          .set(followData);
        await firestoreMod()
          .collection('users')
          .doc(post.userId)
          .collection('followers')
          .doc(currentUserId)
          .set(followerData);
        
        setIsFollowing(true);
        
        // Notification will be sent by Firebase Functions
      }
    } catch (error) {
      console.log('Error following/unfollowing:', error);
    }
  };
                    
  // Simplified rendering for post detail
  const renderPostContent = () => {
    try {
      const hasVideo = post.playbackUrl || (post.media && isVideoAsset(post.media));
      const hasAudioOnly =
        (!post.playbackUrl && !!post.audio?.uri) ||
        (!post.playbackUrl && post.media && isAudioAsset(post.media));
      const hasImage = post.media && isImageAsset(post.media);
      const hasDocument =
        post.media &&
        !isVideoAsset(post.media) &&
        !isAudioAsset(post.media) &&
        !isImageAsset(post.media);
      const hasText = post.captionText || post.link;
                    
      return (
        <View style={{ flex: 1 }}>
          {/* Video or Image */}
          {hasVideo && RNVideo ? (
            isOffline ? (
              <View
                style={{
                  width: SCREEN_WIDTH,
                  height: SCREEN_HEIGHT,
                  alignItems: 'center',
                  justifyContent: 'center',
                  backgroundColor: '#000',
                  paddingHorizontal: 24,
                }}
              >
                <Text style={{ fontSize: 40, marginBottom: 12 }}>📴</Text>
                <Text style={{ color: '#fff', fontWeight: '800', fontSize: 18, marginBottom: 6 }}>
                  Video unavailable offline
                </Text>
                <Text style={{ color: 'rgba(255,255,255,0.76)', textAlign: 'center' }}>
                  Reconnect to the internet to play this video.
                </Text>
              </View>
            ) : (
              <VideoWithTapControls
                source={{ uri: String(post.playbackUrl || post.media.uri) }}
                style={{ width: SCREEN_WIDTH, height: SCREEN_HEIGHT }}
                resizeMode="cover"
                paused={!isFocused}
                muted={true}
                maxBitRate={1500000}
                bufferConfig={{
                  minBufferMs: 20000,
                  maxBufferMs: 60000,
                  bufferForPlaybackMs: 5000,
                  bufferForPlaybackAfterRebufferMs: 10000,
                }}
                useTextureView={false}
                progressUpdateInterval={750}
                poster={String(post.media?.uri || post.playbackUrl)}
                posterResizeMode="cover"
                disableFocus={true}
                playInBackground={false}
                playWhenInactive={false}
                ignoreSilentSwitch="ignore"
                onLoad={(e: any) => {
                  setPlaybackDuration(e?.duration || 0);
                  incrementViews();
                }}
                onProgress={(e: any) => {
                  setPlaybackTime(e?.currentTime || 0);
                }}
                onPlay={() => {
                  recordVideoReach(post.id).catch(error => {
                    console.log('Reach recording failed:', error.message);
                  });
                }}
              />
            )
          ) : hasImage ? (
            <View style={{ flex: 1, backgroundColor: 'black' }}>
              <Image
                source={{ uri: post.media.uri }}
                style={{ width: '100%', height: post.audio?.uri ? '82%' : '100%' }}
                resizeMode="contain"
                onLoad={(event) => {
                  // Record image reach when image loads in post detail view
                  recordImageReach(post.id).catch(error => {
                    console.log('Image reach recording failed:', error.message);
                  });
                  // Optionally adjust aspect ratio based on actual image dimensions
                  const { width, height } = event.nativeEvent.source;
                  if (width && height) {
                    // Could update state to adjust dimensions, but for now keep simple
                    console.log('Image loaded with dimensions:', width, height);
                  }
                }}
              />
              {post.audio?.uri && RNVideo ? (
                <View
                  style={{
                    paddingHorizontal: 16,
                    paddingBottom: 10,
                    backgroundColor: 'rgba(0,0,0,0.55)',
                  }}
                >
                  <Text style={{ color: 'rgba(255,255,255,0.78)', fontSize: 12, marginBottom: 6 }}>
                    Overlay audio
                  </Text>
                  <RNVideo
                    source={{ uri: String(post.audio.uri) }}
                    audioOnly
                    controls
                    paused={!isFocused}
                    style={{ width: '100%', height: 62 }}
                    playInBackground={false}
                    playWhenInactive={false}
                    ignoreSilentSwitch="ignore"
                  />
                </View>
              ) : null}
            </View>
          ) : hasAudioOnly && RNVideo ? (
            <View
              style={{
                width: SCREEN_WIDTH,
                minHeight: 220,
                justifyContent: 'center',
                alignItems: 'center',
                backgroundColor: '#000',
                paddingHorizontal: 20,
              }}
            >
              <Text style={{ fontSize: 42, marginBottom: 10 }}>🎵</Text>
              <Text style={{ color: '#cfe9ff', marginBottom: 10 }}>
                Audio post
              </Text>
              <RNVideo
                source={{
                  uri: String(post.audio?.uri || post.media?.uri || ''),
                }}
                audioOnly
                controls
                paused={!isFocused}
                style={{ width: SCREEN_WIDTH - 40, height: 64 }}
                playInBackground={false}
                playWhenInactive={false}
                ignoreSilentSwitch="ignore"
              />
            </View>
          ) : hasDocument ? (
            <View
              style={{
                width: SCREEN_WIDTH,
                minHeight: 220,
                justifyContent: 'center',
                alignItems: 'center',
                backgroundColor: '#000',
                paddingHorizontal: 20,
              }}
            >
              <Text style={{ fontSize: 42, marginBottom: 10 }}>📄</Text>
              <Text style={{ color: '#cfe9ff' }}>Document attachment</Text>
            </View>
          ) : null}
                    
          {/* Text */}
          {hasText && (
            <View style={{ padding: 20 }}>
              {(() => {
                // Record text reach when text content is displayed
                if (!hasImage && !hasVideo) {
                  recordTextReach(post.id).catch(error => {
                    console.log('Text reach recording failed:', error.message);
                  });
                }
                return null;
              })()}
              {post.captionText && (
                <ClickableTextWithLinks
                  text={post.captionText}
                  style={{ color: 'white', fontSize: 18, marginBottom: 10, lineHeight: 26 }}
                />
              )}
              {post.link && (
                <Pressable
                  onPress={() => {
                    Linking.openURL(post.link).catch(err => 
                      console.log('Failed to open link:', err)
                    );
                  }}
                  style={{ 
                    backgroundColor: '#E3F2FD', 
                    padding: 12, 
                    borderRadius: 6,
                    borderWidth: 1,
                    borderColor: '#2196F3',
                    marginTop: 10
                  }}
                >
                  <Text style={{ 
                    color: '#1976D2', 
                    fontSize: 16, 
                    textDecorationLine: 'underline' 
                  }}>
                    {post.link}
                  </Text>
                </Pressable>
              )}
            </View>
          )}
        </View>
      );
    } catch (error) {
      return (
        <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
          <Text style={{ color: 'white' }}>Error loading post content: {String(error)}</Text>
        </View>
      );
    }
  };
                    
  return (
    <View style={{ flex: 1, backgroundColor: '#0A1929' }}>
      
      {/* Minimize/Zoom Out Button */}
      <Pressable
        onPress={() => navigation.goBack()}
        style={{
          position: 'absolute',
          bottom: 80, // Position just above the video time counter
          right: 20,
          zIndex: 10,
          backgroundColor: 'rgba(0,0,0,0.5)',
          padding: 10,
          borderRadius: 20,
        }}
      >
        <Text style={{ color: 'white', fontSize: 18 }}>⤢</Text>
      </Pressable>
      
      {/* Follow Button */}
      {currentUserId && post.userId && currentUserId !== post.userId && (
        <Pressable
          onPress={() => {
            console.log('Follow button pressed');
            handleFollow();
          }}
          style={{
            position: 'absolute',
            top: 50,
            right: 20,
            zIndex: 10,
            backgroundColor: isFollowing ? 'rgba(0,194,255,0.8)' : 'rgba(0,0,0,0.5)',
            padding: 10,
            borderRadius: 20,
          }}
        >
          <Text style={{ color: 'white', fontSize: 16 }}>
            {isFollowing ? '✓ Connected' : '+ Connect CMEE'}
          </Text>
        </Pressable>
      )}
      
      {/* Post Content */}
      {renderPostContent()}
    </View>
  );
}
                    
